import math
from sympy import primerange
L = 1
for N in range(1, 601):
    L = L*N//math.gcd(L, N)
    P = 1
    for p in primerange(2, N+1):
        k = p
        while k <= N:
            P *= p; k *= p
    assert P == L
def theta(y):
    return sum(math.log(p) for p in primerange(2, int(y)+1))
def psi(x):
    t = 0.0
    for p in primerange(2, int(x)+1):
        k = p
        while k <= x:
            t += math.log(p); k *= p
    return t
for x in [10, 1000, 12345.6]:
    s = 0.0; k = 1
    while x**(1/k) >= 2:
        s += theta(x**(1/k)); k += 1
    assert abs(psi(x) - s) < 1e-7
